import React, { useState, useCallback } from 'react';
import {
  Stack,
  Cluster,
  Heading,
  Text,
  Badge,
  Divider,
  SegmentedControl,
  SegmentedControlItem,
  Slider,
  Switch,
  RadioGroup,
  RadioGroupItem,
  Card,
  FieldLabel,
} from '@jinx-ui/react';

type ThemeOption = 'light' | 'dark' | 'system';
type FontOption = 'system' | 'rounded' | 'mono';

export interface AppearanceSettings {
  theme: ThemeOption;
  scale: number;
  dense: boolean;
  font: FontOption;
}

export interface AppearanceSettingsScreenProps {
  initialSettings?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<ThemeOption, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const defaultSettings: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

const AppearanceSettingsScreen: React.FC<AppearanceSettingsScreenProps> = ({
  initialSettings,
  onChange,
}) => {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...defaultSettings,
    ...initialSettings,
  });

  const update = useCallback(
    <K extends keyof AppearanceSettings>(key: K, value: AppearanceSettings[K]) => {
      setSettings((prev) => {
        const next = { ...prev, [key]: value };
        onChange?.(next);
        return next;
      });
    },
    [onChange]
  );

  return (
    <Stack gap="var(--jx-space-6)" className="jx-p-6">
      <Cluster justify="space-between" align="center">
        <Heading level={1} size="lg">
          Внешний вид
        </Heading>
        <Badge tone="neutral">{themeLabels[settings.theme]}</Badge>
      </Cluster>

      <Card padding="var(--jx-space-5)">
        <Stack gap="var(--jx-space-6)">
          <Stack gap="var(--jx-space-2)">
            <FieldLabel>Тема</FieldLabel>
            <SegmentedControl
              value={settings.theme}
              onChange={(value) => update('theme', value as ThemeOption)}
            >
              <SegmentedControlItem value="light">Светлая</SegmentedControlItem>
              <SegmentedControlItem value="dark">Тёмная</SegmentedControlItem>
              <SegmentedControlItem value="system">Системная</SegmentedControlItem>
            </SegmentedControl>
          </Stack>

          <Stack gap="var(--jx-space-2)">
            <Cluster justify="space-between" align="center">
              <FieldLabel htmlFor="ui-scale-slider">Масштаб интерфейса</FieldLabel>
              <Text size="sm" tone="muted">
                {settings.scale}%
              </Text>
            </Cluster>
            <Slider
              id="ui-scale-slider"
              min={80}
              max={140}
              step={5}
              value={settings.scale}
              onChange={(value) => update('scale', value as number)}
              aria-valuetext={`${settings.scale}%`}
            />
          </Stack>

          <Cluster justify="space-between" align="center">
            <Stack gap="var(--jx-space-1)">
              <FieldLabel htmlFor="dense-layout-switch">Плотная вёрстка</FieldLabel>
              <Text size="sm" tone="muted">
                Уменьшает отступы и высоту элементов
              </Text>
            </Stack>
            <Switch
              id="dense-layout-switch"
              checked={settings.dense}
              onChange={(checked) => update('dense', checked)}
            />
          </Cluster>

          <Divider />

          <Stack gap="var(--jx-space-3)">
            <Heading level={2} size="sm">
              Ещё
            </Heading>
            <Stack gap="var(--jx-space-2)">
              <FieldLabel>Шрифт</FieldLabel>
              <RadioGroup
                value={settings.font}
                onChange={(value) => update('font', value as FontOption)}
              >
                <RadioGroupItem value="system">Системный</RadioGroupItem>
                <RadioGroupItem value="rounded">Скруглённый</RadioGroupItem>
                <RadioGroupItem value="mono">Моноширинный</RadioGroupItem>
              </RadioGroup>
            </Stack>
          </Stack>
        </Stack>
      </Card>
    </Stack>
  );
};

export default AppearanceSettingsScreen;

